uint8_t nibble(char c){return uint8_t(c<='9'?c-'0':c-'a'+10);}
std::vector<uint8_t> hex_bytes(const std::string&s){assert(s.size()%2==0);std::vector<uint8_t>v(s.size()/2);for(size_t i=0;i<v.size();++i)v[i]=uint8_t(nibble(s[2*i])<<4|nibble(s[2*i+1]));return v;}
context_store_format_digest digest(const char*s){auto v=hex_bytes(s);assert(v.size()==32);context_store_format_digest d{};std::copy(v.begin(),v.end(),d.begin());return d;}
context_store_registered_id id(const char*s){context_store_registered_id x;while(s[x.size]){x.bytes[x.size]=s[x.size];++x.size;}return x;}
std::string value(const std::string&json,const std::string&key,size_t from=0){auto p=json.find("\""+key+"\"",from);assert(p!=std::string::npos);p=json.find(':',p)+1;p=json.find('"',p)+1;auto e=json.find('"',p);return json.substr(p,e-p);}
std::vector<uint8_t> fixture(const std::string&json,const char*name){auto p=json.find("\""+std::string(name)+"\"");assert(p!=std::string::npos);return hex_bytes(value(json,"envelope_hex",p));}
