 setup(uint64_t high=40,uint64_t delta=1){secret.fill(0x44);credential.key_id=id("registry-auth-v1");credential.generation=13;credential.secret=secret;context_store_protected_registry_key_record k{context_store_key_disposition::active,credential.key_id,13,{secret.data(),secret.size()}};context_store_protected_registry_body pb;pb.registry_id=id("registry-v1");pb.registry_epoch=9;pb.authority_base_scope_commitment.fill(0xaa);pb.policy_commitment.fill(0xbb);pb.last_consumed_sequence=high;auto pe=context_store_encode_protected_registry_v1(pb,k,pred.data(),pred.size());assert(pe.authenticated_carrier());context_store_protected_registry_successor_body sb;sb.registry_id=pb.registry_id;sb.registry_epoch=9;sb.authority_base_scope_commitment=pb.authority_base_scope_commitment;sb.policy_commitment=pb.policy_commitment;sb.consumed_authorization_high_water=high+delta;sb.predecessor_snapshot_envelope_digest=*pe.authenticated_carrier()->envelope_digest();sb.receipt.authorization_sequence=high+delta;sb.receipt.command_id.fill(0xcc);sb.receipt.authorization_token_digest.fill(0xdd);sb.receipt.plan_commitment.fill(0xee);sb.receipt.selected_manifest_digest.fill(0x11);sb.receipt.proposed_anchor_envelope_digest.fill(0x22);auto se=context_store_encode_protected_registry_successor_v1(sb,k,succ.data(),succ.size());assert(se.authenticated_carrier());expect.root_id.fill(0x11);expect.store_uuid.fill(0x22);expect.filesystem_uuid.fill(0x44);expect.registry_id=pb.registry_id;expect.registry_epoch=9;expect.predecessor_high_water=high;expect.predecessor_selector_generation=1;expect.successor_selector_generation=2;expect.mount_id=731;expect.owner_uid=1000;expect.lock_st_dev=2049;expect.lock_st_ino=987654;expect.path_policy_commitment=digest("162c7c9272841ccdec5dbf024d1d8dd511dbb4e2f538d8cdbab830e06abc9c0d");expect.initial_head_digest=digest("93ea1f031d4ec2827bc28535d56f2a0a1f6efb49ecff9ed763cf03bced0c0d82");expect.successor_head_digest=digest("d3d372ef42c5254a2baca52ba35cae46899cdf0e464396e3fa272ffc238a309b");expect.predecessor_envelope_digest=digest("5b6ea5887d96bf20c176e2346c2478149a8b7bcf1d84dc98843c28f4e00d0b9e");expect.successor_envelope_digest=digest("ee621ab3efa4c76cc2e2132034a404d6a373701ad8772f0576fd5bd20087c5cd");expect.prepare_digest=digest("9ea5eced3354b6a90ca306361568de879d5ebfc9effd63de6f73629c04baa8fa");expect.operation_commitment=digest("f28cb18e21d74d63346bddacbd482e28a55989cfa2f9e18cea382792a89b7fb1");expect.attempt_id.fill(0x66);expect.quarantine_event_id.fill(0x77);expect.quarantine_attributable=true;expect.quarantine_has_previous_record=true;expect.quarantine_previous_record_digest=expect.prepare_digest;expect.quarantine_has_head=true;expect.quarantine_head_digest=expect.successor_head_digest;expect.quarantine_reason=6;expect.quarantine_phase=2;expect.slot=17;expect.predecessor=pred.data();expect.predecessor_size=pe.encoded_size;expect.successor=succ.data();expect.successor_size=se.encoded_size;}
